namespace {
size_t checks=0;
void check(bool value,const char*why){if(!value)throw std::runtime_error(why);++checks;}
bool refuses(auto f){try{f();return false;}catch(const std::exception&e){std::cout<<"REFUSAL "<<e.what()<<std::endl;return true;}}
std::string bytes(const std::filesystem::path&p){std::ifstream f(p,std::ios::binary);return {std::istreambuf_iterator<char>(f),{}};}
struct Fixture{Scene scene;uint64_t source=0,target=0;};
Fixture fixture(bool hdr,bool prepared,bool authored,bool physical=false){
 Mesh raw;raw.positions={{-.6f,-.6f,0},{.6f,-.6f,0},{.6f,.6f,0},{-.6f,.6f,0}};raw.normals.assign(4,{0,0,1});raw.uv={{{0,0}},{{1,0}},{{1,1}},{{0,1}}};raw.indices={0,1,2,0,2,3};
 auto maps=std::make_shared<PaintSourceMaps>();maps->emission.image=std::make_shared<const Image>(Image{2,2,{255,0,0,255,0,0,255,255,255,0,0,255,0,0,255,255}});maps->emission.texcoord=0;maps->emission.min_filter=maps->emission.mag_filter=9729;
 auto logical=std::make_shared<std::vector<std::array<float,2>>>(raw.uv);for(auto&q:*logical)q[0]=1-q[0];if(!prepared){maps->uv1=logical;maps->emission.texcoord=1;}
 auto paint=capture_source_sampling(raw,maps,64);if(prepared){auto atlas=raw;for(auto&q:atlas.uv){q[0]=.125f+.75f*q[0];q[1]=.125f+.75f*q[1];}const std::array<uint32_t,4>ids{0,1,2,3};paint=authored?prepare_source_paint(paint,atlas,ids,logical,{}):prepare_source_paint(paint,atlas,ids);}
 Fixture result;auto&o=result.scene.active();result.source=o.id;o.visible=false;o.mesh_active=true;o.painted=paint;o.material.emissive=hdr?std::array<float,3>{2,1,4}:std::array<float,3>{.5f,.25f,1};
 auto binding=std::make_shared<SourceMaterialBindings>();binding->has_mtoon=true;binding->native_reference.emission=o.material.emissive;binding->material=MToonMaterial::from_vrm1({{"extensions",{{"VRMC_materials_mtoon",{{"specVersion","1.0"}}}}}});binding->material.parameters.emission={.5f,.25f,1};binding->material.parameters.emission_strength=hdr?4:1;auto&slot=binding->material.textures[size_t(MToonSlot::Emission)];slot.index=0;slot.texcoord=1;slot.encoding=MToonEncoding::Srgb;binding->roles[size_t(MToonSlot::Emission)]=maps->emission;binding->roles[size_t(MToonSlot::Emission)].texcoord=0;if(physical)binding->physical_emission=std::array<float,3>{8,4,2};binding->validate();o.material_bindings=binding;
 result.target=result.scene.add("Independent native target",Volume{});auto&t=result.scene.object(result.target);t.mesh_active=true;t.painted=std::make_shared<PaintedMesh>(raw,64);result.scene.select(result.target);result.scene.validate();return result;
}
ObjectBakeSettings settings(){ObjectBakeSettings value;value.front_mm=value.back_mm=2;value.padding=0;value.ao_samples=0;return value;}
void positive(bool hdr,bool prepared,bool physical,const std::filesystem::path&out){std::cout<<"POSITIVE_BEGIN hdr="<<hdr<<" prepared="<<prepared<<" physical="<<physical<<std::endl;auto f=fixture(hdr,prepared,true,physical);const auto before=f.scene.encode();check(Scene::decode(before).encode()==before,"Valid genuine UV1 native roundtrip differs");const auto source=f.scene.object(f.source).painted;const auto binding=f.scene.object(f.source).material_bindings;
 const auto callback=detail::emission_bake_source(f.scene.object(f.source));check(bool(callback)==(hdr||physical),"Valid nonHDR legacy selector changed");if(callback){const auto value=callback(0,{.2f,.3f,.5f});const std::array<float,3>expected=physical?std::array<float,3>{8,4,2}:std::array<float,3>{1.8f,0,.4f};for(size_t k=0;k<3;++k)check(std::abs(value[k]-expected[k])<=2e-6f,"Valid genuine typed UV1/physical background sample changed");}
 check(bool(detail::raw_bake_source(f.scene.object(f.source))),"Valid genuine original/current source capture refused");const auto baseline=f.scene.snapshot();const auto report=bake_object(f.scene,f.source,settings());check(report.projected==4096&&f.scene.object(f.source).painted==source&&f.scene.object(f.source).material_bindings==binding,"Valid actual Bake lost original source owners");const auto after=f.scene.encode();
 Document doc;doc.replace(baseline);check(doc.wait_mesh()&&doc.frame().state->error.empty(),"Valid source did not publish");doc.bake_from_object(f.source,settings());const auto path=out/((hdr?std::string("hdr-"):std::string("ldr-"))+(physical?"physical":prepared?"prepared":"unprepared")+".dsculpt");auto save=doc.save_async(path);save.get();check(doc.wait_asset(std::chrono::seconds(120))&&doc.wait_mesh()&&doc.frame().state->error.empty()&&doc.copy_scene().encode()==after&&Scene::load(path).encode()==after,"Valid source worker/orderedSave/reopen differs");check(doc.undo()&&doc.wait_mesh()&&doc.copy_scene().encode()==before&&doc.redo()&&doc.wait_mesh()&&doc.copy_scene().encode()==after,"Valid source Bake Undo/Redo differs");std::cout<<"VALID_ROLE hdr="<<hdr<<" prepared="<<prepared<<" physical="<<physical<<" projected="<<report.projected<<" worker/save/history=exact"<<std::endl;
}
size_t missing(bool hdr,const std::filesystem::path&out){auto f=fixture(hdr,true,false);const auto before=f.scene.encode();check(Scene::decode(before).encode()==before,"Existing editable missing-role Scene wire changed");const auto&source=f.scene.object(f.source);check(source.painted->source_sampling_prepared()&&!source.painted->source_sampling_authored_uv1()&&!source.painted->source_sampling_original()->source_maps()->uv1&&source.painted->source_maps()->uv1,"Missing logical domain fixture is not genuine");
 const bool emitter=refuses([&]{const auto callback=detail::emission_bake_source(source);if(callback){const auto value=callback(0,{.2f,.3f,.5f});std::cout<<"SILENT_CALLBACK hdr="<<hdr<<" value="<<value[0]<<','<<value[1]<<','<<value[2]<<std::endl;}else std::cout<<"SILENT_CALLBACK hdr=0 legacy_empty=1"<<std::endl;});const bool raw=refuses([&]{detail::raw_bake_source(source);});auto trial=f.scene.snapshot();const bool bake=refuses([&]{const auto report=bake_object(trial,f.source,settings());std::cout<<"SILENT_BAKE hdr="<<hdr<<" projected="<<report.projected<<std::endl;});check(!bake||trial.encode()==before,"Missing logical UV1 refusal changed source/target state");check(f.scene.encode()==before,"Original role captures changed authority");
 auto cancelled=f.scene.snapshot();check(refuses([&]{bake_object(cancelled,f.source,settings(),[]{return true;});})&&cancelled.encode()==before,"Missing role cancellation changed source/target state");check(refuses([&]{detail::emission_bake_source(source,[]{return true;});})&&f.scene.encode()==before,"Cancelled missing role emitter changed authority");
 const auto path=out/(hdr?"hdr-prior.dsculpt":"ldr-prior.dsculpt");const std::string prior="Prior native path bytes must remain exact\n";{std::ofstream file(path,std::ios::binary);file<<prior;}
 Document doc;doc.replace(f.scene.snapshot());check(doc.wait_mesh(),"Missing role fixture failed unrelated geometry publication");const auto initial=doc.frame().state;bool saved=true;try{doc.bake_from_object(f.source,settings());auto save=doc.save_async(path);save.get();}catch(const std::exception&e){saved=false;std::cout<<"DEPENDENT_SAVE_REFUSAL hdr="<<hdr<<" "<<e.what()<<std::endl;}
 check(doc.wait_asset(std::chrono::seconds(120))&&doc.wait_mesh(),"Missing role worker did not reach an owning terminal boundary");const auto state=doc.frame().state;const bool atomic=!saved&&doc.copy_scene().encode()==before&&!state->can_undo&&!state->can_redo&&state->project_path==initial->project_path&&bytes(path)==prior;std::cout<<"MISSING_ROLE hdr="<<hdr<<" emitter_refuses="<<emitter<<" raw_refuses="<<raw<<" Bake_refuses="<<bake<<" dependentSave_refuses="<<!saved<<" exact_data_path_history="<<atomic<<" error="<<state->error<<std::endl;return size_t(!emitter)+size_t(!raw)+size_t(!bake)+size_t(!atomic);
}
}
int main(int argc,char**argv)try{check(argc==2,"Output directory required");const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);for(bool hdr:{false,true})for(bool prepared:{false,true})positive(hdr,prepared,false,out);positive(true,true,true,out);size_t errors=0;for(bool hdr:{false,true})errors+=missing(hdr,out);check(errors==0,"Missing logical UV1 silently aliases generated PBR carrier or changes save/history state");std::cout<<"PASS "<<checks<<" missing logical typed UV1 source controls"<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
